    const nr = turm.steine.length + 1;
    for (let i = hi0; i <= hi1; i++) if (H_GEN[i] === gen && H_O[i] < turm.oben[i]) { turm.oben[i] = H_O[i]; turm.wer[i] = nr; }
    turm.steine.push({ id: st.id, x: e.x, y: e.y, th: e.th });
