    const grund = p.gesamt >= 95 ? 'Perfekt ausbalanciert' : (PUNKTE.balance - p.balance) >= (PUNKTE.eben - p.eben) ? 'Etwas mittiger setzen' : 'Oberseite etwas schief';
    S.popups.push({ text: '+' + p.gesamt, x: e.x, y: top - 4, t: 0, gut: p.gesamt >= 90, grund });
